    archive.mspa.story['003860'].title = '==>'
    archive.mspa.story['003860'].content = '男孩的悲伤被打断。他的戒指，遭要索。'
    archive.mspa.story['003861'].title = '==>'
    archive.mspa.story['003861'].content = '玩偶认了新主人。该战术，为失策。'
    archive.mspa.story['003862'].title = '==>'
    archive.mspa.story['003862'].content = '将军。'
    archive.mspa.story['003863'].title = '数小时后的未来...'
    archive.mspa.story['003863'].content = '履行者成了反叛者。'
    archive.mspa.story['003864'].title = '回忆起不久之前的过去...'
    archive.mspa.story['003864'].content = '一座寺庙遭逃离。不久之后，重返。'
    archive.mspa.story['003865'].title = '==>'
    archive.mspa.story['003865'].content = '一个附近的实验室也遭重返。它的卫星，已调离。'
    archive.mspa.story['003866'].title = '==>'
    archive.mspa.story['003866'].content = '一个睡着的男孩被找到。轰隆之声，不祥。'
    archive.mspa.story['003867'].title = '==>'
    archive.mspa.story['003867'].content = '实验室在飞行。它的出口，失效。'
    archive.mspa.story['003868'].title = '==>'
    archive.mspa.story['003868'].content = '又一个公职人员做出牺牲。公民安全，确保。'
    archive.mspa.story['003869'].title = '==>'
    archive.mspa.story['003869'].content = '暴君撤退了。一艘战舰，着陆。'
    archive.mspa.story['003870'].title = '==>'
    archive.mspa.story['003870'].content = ''
    archive.mspa.story['003871'].title = '==>'
    archive.mspa.story['003871'].content = ''
    archive.mspa.story['003872'].title = '==>'
    archive.mspa.story['003872'].content = '一位祖父哀恸。家庭传统，实践。'
    archive.mspa.story['003873'].title = '==>'
    archive.mspa.story['003873'].content = '一位女王哀恸。王国，诀别。'
    archive.mspa.story['003874'].title = '数小时后的未来...'
    archive.mspa.story['003874'].content = '她的风尘仆仆的旅程势必得独自完成。她的随从，告别。<br/><br/>女王成了寻觅者。'
    archive.mspa.story['003875'].title = '而数年后...'
    archive.mspa.story['003875'].content = ''
    archive.mspa.story['003876'].title = '==>'
