    archive.mspa.story['004318'].title = '======>'
    archive.mspa.story['004318'].content = ''
    archive.mspa.story['004319'].title = '======>'
    archive.mspa.story['004319'].content = ''
    archive.mspa.story['004320'].title = '======>'
    archive.mspa.story['004320'].content = ''
    archive.mspa.story['004321'].title = '======>'
    archive.mspa.story['004321'].content = '(2x转埸连埸连击)<br/><br/>OK，那老兄几乎不会搞什么乱子。<br/><br/>那她呢?'
    archive.mspa.story['004322'].title = '输入名字。'
    archive.mspa.story['004322'].content = '妳的名字是 FEFERI PEIXES。'
    archive.mspa.story['004323'].title = 'Feferi：做点俏皮的事。'
    archive.mspa.story['004323'].content = ''
    archive.mspa.story['004324'].title = '======>'
