    archive.mspa.story['005090'].title = '注死Dave：敲Terezi。'
    archive.mspa.story['005090'].content = '|DIALOGLOG|<br/><br/>-- 科技转盘神 turntechGodhead <span style="color: #e00707;">[TG]</span> 开始敲 绞刑台校准者 gallowsCalibrator <span style="color: #008282;">[GC]</span> -- <br/><br/><span style="color: #e00707;">TG: 很好这很明显一点意义都没有<br/><br/>TG: 现在勒<br/><br/>TG: 哈啰 <br/><br/>TG: terezi <br/><br/>TG: 怎么啦</span><br/><br/><span style="color: #008282;">GC: &gt;:[</span>'
