    archive.mspa.story['005191'].title = '==>'
    archive.mspa.story['005191'].content = '一隻奇妙的虫靠了过来。<br/><br/>这肯定是你的幸运日。'
    archive.mspa.story['005192'].title = '==>'
    archive.mspa.story['005192'].content = '<span style="color: #005682">.... . .. / -. .. ！！！！！！！！<br/><br/>-. .. / -.. .- ... ..- .- -. / -. .- / -. .. / -.. . / -. .- / --.. .... .. / .--- .. . --.. .... .. / --.. ..- --- / ... .... . -. -- . ？</span><br/><br/><span style="color: #e1e1e1">嘿你！！！！！！！！<br/><br/>你打算拿你的那只戒指做什么？</span>'
    archive.mspa.story['005193'].title = '==>'
    archive.mspa.story['005193'].content = '<span style="color: #005682">-... ..- / --. ..- .- -. / --.. . -. / -.-- .- -. --. / --..-- / .-- .- -. --. / .-.. . / - .- / -... .-！<br/><br/>-. .- / --. . / ... .... .- / ... .... --- ..- / ... .... .. / .-- --- --- --- --- --- --- --- --- / -.. .  ::::)</span><br/><br/><span style="color: #eaeaea">八管怎样，忘了它叭！<br/><br/>那个杀手是我我我我我我我我的 ::::)</span>'
