    archive.mspa.story['005745'].content = ''
    archive.mspa.story['005746'].title = '[o] 答。'
    archive.mspa.story['005746'].content = ''
    archive.mspa.story['005747'].title = '[o] 叭噗。'
    archive.mspa.story['005747'].content = ''
    archive.mspa.story['005748'].title = '[o] 叭噗。'
