    archive.mspa.story['006657'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd;">JOHN: 不！！！</span><br/><br/><span style="color: #77003c;">MEENAH: 下次灵光点啊傻鱼脸</span><br/><br/><span style="color: #0715cd;">JOHN: 打瞌睡的神秘女孩，小心！！！</span>'
