    archive.mspa.story['006713'].content = ''
    archive.mspa.story['006714'].title = '[A6I2] ==>'
    archive.mspa.story['006714'].content = ''
    archive.mspa.story['006715'].title = '[S][A6I2] ???'
    archive.mspa.story['006715'].content = ''
