    archive.mspa.story['006896'].title = '==>'
    archive.mspa.story['006896'].content = '|DIALOGLOG|<br/><br/><span style="color: #77003c;">MEENAH: 鲠别说自我了断</span>'
    archive.mspa.story['006897'].title = '==>'
    archive.mspa.story['006897'].content = '|DIALOGLOG|<br/><br/><span style="color: #77003c;">MEENAH: 所以我就把大家通通他妈炸了</span>'
    archive.mspa.story['006898'].title = '==>'
    archive.mspa.story['006898'].content = '|DIALOGLOG|<br/><br/><span style="color: #77003c;">MEENAH: 故事就是咕噜的这样</span>'
