    archive.mspa.story['006994'].content = '|DIALOGLOG|<br/><br/><span style="color: #929292;">天王星闇影uranianUmbra [UU]</span> 停止激励 <span style="color: #ff6ff2;">醺灵怀旧tipsyGnostalgic [TG]</span><br/><br/><!-- LOG END --><br/><br/></div> </div>'
    archive.mspa.story['006995'].title = '==>'
    archive.mspa.story['006995'].content = ''
    archive.mspa.story['006996'].title = '==>'
