    archive.mspa.story['007614'].content = '<div>  </div><style>@-webkit-keyframes trickster-glow {0%  {color: #fff6d1;}50% {color: #f0d1ff;}100% {color: #d1ffe3;}}@keyframes trickster-glow {0%  {color: #fff6d1;}50% {color: #f0d1ff;}100% {color: #d1ffe3;}}</style>'
