    archive.mspa.story['007692'].title = '==> ==>'
    archive.mspa.story['007692'].content = '|DIALOGLOG|<br/><br/><span style="color: #00d5f2;">GG: 我觉得它掉到了地窖里。</span><br/><br/><!-- LOG END --><br/><br/></div> </div>'
