    archive.mspa.story['007778'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925;">JADE: 嗨!</span><br/><br/><!-- LOG END --><br/><br/></div> </div>'
    archive.mspa.story['007779'].title = '==> ==>'
    archive.mspa.story['007779'].content = '|DIALOGLOG|<br /><span style="color: #1f9400;">JAKE: ...</span><br /><br /><span style="color: #00d5f2;">JANE: ...</span><br />'
    archive.mspa.story['007780'].title = '==> ==>'
    archive.mspa.story['007780'].content = '|DIALOGLOG||DIALOGLOG|<br/><br/><span style="color: #4ac925;">JADE: 你是jake吗?</span><br/><br/><span style="color: #1f9400;">JAKE: 呃。</span><br/><br/><span style="color: #1f9400;">JAKE: 是。</span><br/><br/><span style="color: #4ac925;">JADE: 嗨jake!</span><br/><br/><span style="color: #4ac925;">JADE: 我是jade</span><br/><br/><span style="color: #4ac925;">JADE: 很高兴终于见到你了!</span><br/><br/><span style="color: #1f9400;">JAKE: 哇。</span><br/><br/><span style="color: #1f9400;">JAKE: 呃呃呃。</span><br/><br/><span style="color: #1f9400;">JAKE: 嗯。</span><br/><br/><span style="color: #4ac925;">JADE: 那你就一定是jane了?</span><br/><br/><span style="color: #00d5f2;">JANE: 我？</span><br/><br/><span style="color: #4ac925;">JADE: 嗯嗯!</span><br/><br/><span style="color: #00d5f2;">JANE: 喔。</span><br/><br/><span style="color: #00d5f2;">JANE: 我...</span><br/><br/><span style="color: #00d5f2;">JANE: 对。</span><br/><br/><span style="color: #4ac925;">JADE: 也很高兴终于见到你喔jane</span><br/><br/><span style="color: #00d5f2;">JANE: 是。</span><br/><br/><!-- LOG END --><br/><br/></div> </div>'
    archive.mspa.story['007781'].title = '==> ==>'
    archive.mspa.story['007781'].content = '|DIALOGLOG|<br /><br /><span style="color: #4ac925;">JADE: 所以呃...</span><br /><br /><span style="color: #4ac925;">JADE: jake</span><br />'
    archive.mspa.story['007782'].title = '==> ==>'
    archive.mspa.story['007782'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925;">JADE: 你的裤子呢?</span><br/><br/><!-- LOG END --><br/><br/></div> </div>'
