    archive.mspa.story['008008'].title = '[A6I5] ==> '
    archive.mspa.story['008008'].content = '|DIALOGLOG|<br/><br/><style>.blur-text { filter: blur(1.3px); }</style><span style="color:#0715cd" class="blur-text">JOHN：哇。</span><br/><br/><span style="color:#0715cd" class="blur-text">JOHN：我觉得好诡异。</span><br/><br/><span style="color: #005682">VRISKA：John，你能把你的手拿出来吗？</span><br/><br/><span style="color: #005682">VRISKA：你正在以一种完全无法界定的方式模煳闪他妈的烁。</span></img>'
