    archive.mspa.story['008189'].title = '[A6A6I1] ====> '
    archive.mspa.story['008189'].content = '|DIALOGLOG|<br/><br/><span style="color: #ff6ff2">ROXY：哟你刚才是不是汪了</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">是的我汪了</span><br/><br/><span style="color: #ff6ff2">ROXY：我知道</span><br/><br/><span style="color: #ff6ff2">ROXY：但看起来你也能用人话交流</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">是的我也能说人话</span><br/><br/><span style="color: #ff6ff2">ROXY：那你为什么要汪而不说人话呢</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">噢不要担心……</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我会和你说很多人话的</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你看，roxy</span>'
