    archive.mspa.story['008190'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我们有好多人事要商量呢</span><br/><br/><span style="color: #ff6ff2">ROXY: （lmao）</span>'
    archive.mspa.story['008191'].title = '[A6A6I1] ====> '
