    archive.mspa.story['008246'].content = '|DIALOGLOG|<br/><br/><span style="color: #b536da">ROSE：为什么光雨地非要<span style="font-style: italic">亮成这样？</span></span>'
    archive.mspa.story['008247'].title = '[A6A6I1] ====> '
