    archive.mspa.story['008384'].title = '==> '
    archive.mspa.story['008384'].content = ''
    archive.mspa.story['008385'].title = '==> '
    archive.mspa.story['008385'].content = ''
    archive.mspa.story['008386'].title = '==> '
    archive.mspa.story['008386'].content = ''
    archive.mspa.story['008387'].title = '==> '
    archive.mspa.story['008387'].content = ''
    archive.mspa.story['008388'].title = '==> '
    archive.mspa.story['008388'].content = ''
    archive.mspa.story['008389'].title = '无视帷幕背后毫不重要的雄性鬼魂。 '
    archive.mspa.story['008389'].content = '他不是这个故事的一部分。'
    archive.mspa.story['008390'].title = '我们继续。 '
    archive.mspa.story['008390'].content = '图：（为什么这里的一切都这么烂。）<br/><br/>ALPHA男老大用这些东西做必要的事情。他的冒险近在眼前。'
    archive.mspa.story['008391'].title = 'ALPHA男老大：出去。 '
    archive.mspa.story['008391'].content = '图：（一切都不是这么发生的你这智障！）<br/><br/>ALPHA男老大和他可靠的婊子大队走上屋顶。见证他所进入的这片梦幻之地。'
    archive.mspa.story['008392'].title = 'ALPHA男老大：上屋顶。 '
    archive.mspa.story['008392'].content = '图：（喂，你以为你在干嘛！我可不会站在一旁看着你这样糟践我们的故事！）（呃啊，这些楼梯也太烂了！它们到底是怎么被判定为楼梯的？！）<br/><br/>你成功地上了屋顶。准备给你可悲的星球一个人类吻别。这里没有一双不流泪的眼睛。除了男老大的。还有人偶的。'
    archive.mspa.story['008393'].title = '突然。出现了戏剧性的转折。 '
    archive.mspa.story['008393'].content = ''
    archive.mspa.story['008394'].title = '我忘了他的星球叫什么了。'
    archive.mspa.story['008394'].content = '好像有岩浆还是什么，我猜？我其实一点儿也不在乎。我会自己给他编一个。这将是一个很好的机会。我在屈伸我强大的“世界观构筑”肌肉好让你眼花缭乱。<br/><br/><br/><br/>你看。在构建一个强有力的、不可抗拒的叙述时。我认为对一个有才的艺术家而言重要的是。给自己自由去做一切他想做的事。尽一个智天使能使出的全力去胡搞。而自由的维度应该是。字面上的。像他妈的整个故事一样大。<br/><br/><br/><br/>就是这样。利用我从无尽的艺术家知识中积累累的知识。我要改变我的“画风”。来展示我的多才多艺。来给你留下深刻的印象。<br/><br/><br/><br/>但是。漫画对现在来说显然还太超前了。在我提高我的纯艺术水平之后。也许吧。但现在不行。<br/><br/><br/><br/>所以现在就这样了。为了得到更多的练习。我的全部世界名画。都将剽窃自举世闻名的EMBERLY先生。'
    archive.mspa.story['008395'].title = '哇哦。好耶。真棒。 '
    archive.mspa.story['008395'].content = ''
    archive.mspa.story['008396'].title = 'ALPHA男老大：用口哨召唤种马。 '
    archive.mspa.story['008396'].content = '你召唤了一群高贵的坐骑。你的聚会需要它们。让它们在我美丽的奇迹领中驰骋。'
    archive.mspa.story['008397'].title = '种马：下降。 '
    archive.mspa.story['008397'].content = 'ALPHA男大哥的冒险年代从此开始。从这个屋顶上。俯瞰迷人的悬崖。统治无数华丽的种马。<br/><br/><br/><br/>多么讽刺。他独一无二的启程。是从一群马的附近。什么。你没听懂？那就再好好想想。<br/><br/><br/><br/>好好想想。'
    archive.mspa.story['008398'].title = '乘上坐骑。 '
    archive.mspa.story['008398'].content = '你们所有的聚会成员都乘上了雄伟的负重之兽。准备像风一样驰骋。<br/><br/><br/><br/>不用说。不完整的马。必须留给女人。'
    archive.mspa.story['008399'].title = '坐骑：被骑。 '
    archive.mspa.story['008399'].content = '图：（等等！！！）（呃啊，一群白痴！）<br/><br/>他们走啦！看看他们。'
