    archive.mspa.story['008466'].content = '|DIALOGLOG|<br/><br/><span style="color: #77003c">MEENAH：大嗓门短角仔</span><br/><br/><span style="color: #77003c">MEENAH：快点儿大嗓门</span><br/><br/><span style="color: #77003c">MEENAH：看到消息了没</span><br/><br/><span style="color: #626262">KARKAT：什么？</span><br/><br/><span style="color: #626262">KARKAT：你谁。</span>'
    archive.mspa.story['008467'].title = '[A6A6I2] ====> '
    archive.mspa.story['008467'].content = '|DIALOGLOG|<br/><br/><span style="color: #77003c">MEENAH：大嗓门是你吗</span><br/><br/><span style="color: #626262">KARKAT：是啊。</span><br/><br/><span style="color: #626262">KARKAT：不我是说，不是。</span><br/><br/><span style="color: #626262">KARAKT：我是KARKAT。</span><br/><br/><span style="color: #626262">KARAKT：你是</span><br/><br/><span style="color: #626262">KARKAT：你是MEENAH？</span><br/><br/><span style="color: #77003c">MEENAH：对</span><br/><br/><span style="color: #626262">KARKAT：哦。</span><br/><br/><span style="color: #626262">KARKAT：嘿</span><br/><br/><span style="color: #626262">KARKAT：好久不，呃</span><br/><br/><span style="color: #626262">KARKAT：我还以为我再也不会收到你的消息了。</span><br/><br/><span style="color: #626262">KARKAT：我不是在叫你滚开什么的，我只是很惊讶。</span><br/><br/><span style="color: #626262">KARKAT：你最近过得怎么样</span><br/><br/><span style="color: #626262">KARKAT：我是说……</span><br/><br/><span style="color: #626262">KARKAT：当我没说。这是个蠢问题。</span><br/><br/><span style="color: #626262">KARKAT：你是鬼魂。</span><br/><br/><span style="color: #626262">KARKAT：你现在还是鬼魂，对吧？</span><br/><br/><span style="color: #626262">KARKAT：呃</span><br/><br/><span style="color: #626262">KARKAT：嘿你看</span><br/><br/><span style="color: #626262">KARKAT：我知道当我准备加入你的军队时我们做了那些初步的规划。</span><br/><br/><span style="color: #626262">KARKAT：然后我想那应该不会有什么真正的结果，因为……</span><br/><br/><span style="color: #626262">KARKAT：我不知道。我猜后来又出了狗屎的问题？</span><br/><br/><span style="color: #626262">KARKAT：你知道事情总是那样的。</span><br/><br/><span style="color: #626262">KARKAT：但不管怎样我还是很抱歉我后来再也没有见过你，也没联系过你，也没……</span><br/><br/><span style="color: #626262">KARKAT：你知道吗？我甚至不知道给你打电话是一个他妈的可选选项。</span><br/><br/><span style="color: #626262">KARKAT：也许应该有人来告诉我真的有这种他妈的可能性？？？</span><br/><br/><span style="color: #626262">KARKAT：我知道，这是多么疯狂的想法。多么有用、多么切实可行的信息正在以某种方式传入我操他妈的生……</span><br/><br/><span style="color: #77003c">MEENAH：大嗓门你他妈的给我把嘴闭上</span>'
