    archive.mspa.story['008470'].content = '|DIALOGLOG|<br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">Crocker呼叫Harley。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">快点儿Harley。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">看到消息了吗？</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">看到了:B</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">我建议你立即来蛮荒之地一趟。</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">什么事</span>'
