    archive.mspa.story['008498'].content = '|DIALOGLOG|<br/><br/><span style="color: #ff6ff2">ROXY：噫呃</span>'
    archive.mspa.story['008499'].title = '[A6A6I2] ====> '
    archive.mspa.story['008499'].content = '|DIALOGLOG|<br/><br/><span style="color: #ff6ff2">ROXY：好啦我想我还是就这么保持隐身一阵子吧</span>'
    archive.mspa.story['008500'].title = '[A6A6I2] ====> '
    archive.mspa.story['008500'].content = ''
    archive.mspa.story['008501'].title = '[A6A6I2] ====> '
    archive.mspa.story['008501'].content = ''
    archive.mspa.story['008502'].title = '[A6A6I2] ====> '
    archive.mspa.story['008502'].content = '|DIALOGLOG|<br/><br/><span style="color: #e00707">ARQUIUSPRITE: <img src="http://www.mspaintadventures.com/storyfiles/hs2/scraps/arquius_shades.png" border="0" />  我的天……</img></span><br/><br/><span style="color: #f2a400">DAVESPRITE：怎</span>'
    archive.mspa.story['008503'].title = '[A6A6I2] ====> '
    archive.mspa.story['008503'].content = '|DIALOGLOG|<br/><br/><span style="color: #e00707">ARQUIUSPRITE: <img src="http://www.mspaintadventures.com/storyfiles/hs2/scraps/arquius_shades.png" border="0" />  这股力量……</img></span>'
    archive.mspa.story['008504'].title = '[A6A6I2] ====> '
    archive.mspa.story['008504'].content = '|DIALOGLOG|<br/><br/><span style="color: #e00707">ARQUIUSPRITE: <img src="http://www.mspaintadventures.com/storyfiles/hs2/scraps/arquius_shades.png" border="0" />  它……</img></span><br/><br/><span style="color: #e00707">ARQUIUSPRITE: <img src="http://www.mspaintadventures.com/storyfiles/hs2/scraps/arquius_shades.png" border="0" />  超出了……</span><br/><br/><span style="color: #f2a400">DAVESPRITE：超出了什么</span>'
    archive.mspa.story['008505'].title = '[A6A6I2] ====> '
    archive.mspa.story['008505'].content = '|DIALOGLOG|<br/><br/><span style="color: #e00707">ARQUIUSPRITE: <img src="http://www.mspaintadventures.com/storyfiles/hs2/scraps/arquius_shades.png" border="0" />  它在总量上超出了那个范围</img></span>'
    archive.mspa.story['008506'].title = '[A6A6I2] ====> '
    archive.mspa.story['008506'].content = '|DIALOGLOG|<br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">Jake，立即停止充能。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你正在毁坏帝国财产！</span>'
    archive.mspa.story['008507'].title = '[A6A6I2] ====> '
    archive.mspa.story['008507'].content = '|DIALOGLOG|<br/><br/><span style="color: #005682">ARANEA：我可不认为他这会儿能听见你说话。</span><br/><br/><span style="color: #005682">ARANEA：希望力场几乎可以说是完全不可穿透的！</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你是谁？</span><br/><br/><span style="color: #005682">ARANEA：谁。我？</span><br/><br/><span style="color: #005682">ARANEA：噢........</span>'
    archive.mspa.story['008508'].title = '[A6A6I2] ====> '
    archive.mspa.story['008508'].content = '|DIALOGLOG|<br/><br/><span style="color: #005682">ARANEA：我是一介无名小卒。</span>'
    archive.mspa.story['008509'].title = '[A6A6I2] ====> '
    archive.mspa.story['008509'].content = '|DIALOGLOG|<br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">Harley。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你去收拾Jake。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">我来处理这个自恋troll。</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">好！</span>'
    archive.mspa.story['008510'].title = '[A6A6I2] ====> '
    archive.mspa.story['008510'].content = ''
    archive.mspa.story['008511'].title = '[A6A6I2] ====> '
    archive.mspa.story['008511'].content = ''
    archive.mspa.story['008512'].title = '[A6A6I2] ====> '
    archive.mspa.story['008512'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">抱歉啰jake你听到那位女士是怎么说的了</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你真是把这个崇高的地方搞得一团糟</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">所以我必须把你传送到寰宇极界里去！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">所以我要说的就是你实在太调皮太无法无天了所以现在只好让你先滚出去</span><br/><br/><img border="0" src="https://www.homestuck.com/images/storyfiles/hs2/scraps/jake_bigtext1.gif"/>'
    archive.mspa.story['008513'].title = '[A6A6I2] ====> '
    archive.mspa.story['008513'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">什么</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">为什么……</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">为什么我……</span>'
    archive.mspa.story['008514'].title = '[A6A6I2] ====> '
    archive.mspa.story['008514'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">为什么我不能把你传送走！</span><br/><br/><img src="http://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext2.gif" border="0" /><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">啊你给我闭嘴！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你大吼大叫的陈词滥调严重伤害到我的狗耳朵了！！！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">jade加油啊</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">专心！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">妈的你专心啊！</span></img>'
    archive.mspa.story['008515'].title = '[A6A6I2] ====> '
    archive.mspa.story['008515'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">呃啊！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">当我不得不盯着他傻逼的小短裤看的时候真的很难专心！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">jake我想看的不是这个！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我永远也不想看我的祖父穿性感小内裤！！！</span><br/><br/><img border="0" src="https://www.homestuck.com/images/storyfiles/hs2/scraps/jake_bigtext3.gif"/>'
    archive.mspa.story['008516'].title = '[A6A6I2] ====> '
    archive.mspa.story['008516'].content = '|DIALOGLOG|<br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你在等什么？</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我的力量……</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">似乎不能……</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">渗入……</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">希望力场！！！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">*呼呼*</span><br/><br/><img src="http://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext4.gif" border="0" /><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">而且他一直在瞎折腾！！！</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">我也听到了。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">Jake，你正义的升华确实让我印象深刻。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">但你真的烦到我了。</span><img src="http://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext5.gif" border="0" /><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">噢，看在彼得的份上。</span></img>'
    archive.mspa.story['008517'].title = '[A6A6I2] ====> '
    archive.mspa.story['008517'].content = '|DIALOGLOG|<br/><br/><span style="color: #005682">ARANEA：嗯哼？</span><br/><br/><span style="color: #005682">ARANEA：我记得你说过你要来处理我的。</span><br/><br/><span style="color: #005682">ARANEA：我在等着你呢，Crocker小姐。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你在耍什么花招，troll？</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">说出你对我未来丈夫的企图。</span><br/><br/><span style="color: #005682">ARANEA：别担心，我只是暂时把他借来用作抗衡的力量而已。</span><br/><br/><span style="color: #005682">ARANEA：等我用完他的力量之后，我就要把你的帝国撕碎。::::)</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你休想做到那样的事情。</span><br/><br/><span style="color: #005682">ARANEA：看起来现在你该动手了。</span><br/><br/><span style="color: #005682">ARANEA：我相信你的武器肯定不是摆设。</span><br/><br/><span style="color: #005682">ARANEA：还是说在至高无上的陛下看来她的女继承人只需要用一支训练叉来武装自己就够了？</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">.</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">.</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">我的计算模块认为你有很大概率正在引诱我踏入陷阱。</span><br/><br/><span style="color: #005682">ARANEA：没有什么陷阱，我可以向你保证。</span><br/><br/><span style="color: #005682">ARANEA：我只是单纯地不死而已。</span><br/><br/><span style="color: #005682">ARANEA：你会看到的，只要这美丽的宝物还在我的掌握之中，我就是不朽的存在。</span><br/><br/><span style="color: #005682">ARANEA：甚至比不朽更不朽！</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">比不朽更不朽？</span><br/><br/><span style="color: #005682">ARANEA：没错。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">.</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">.</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">.</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">这真是太蠢了。</span><br/><br/><img src="http://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext3.gif" border="0" /><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">好家伙。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你就不能让他闭嘴吗？</span><br/><br/><span style="color: #005682">ARANEA：很遗憾，不能。</span></img>'
    archive.mspa.story['008518'].title = '[A6A6I2] ====> '
    archive.mspa.story['008518'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">很好，jake</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你赢了</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">既然我没法把你传送走那我就只好让你留下来</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">但我不能允许你继续摧毁老女人的财产</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">所以我要直接把星球掉包！</span>'
    archive.mspa.story['008519'].title = '[A6A6I2] ====> '
    archive.mspa.story['008519'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你忘了我们过去当过笔友吗jake</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我帮你解决过多少棘手的小问题？</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我非常非常非常的聪明</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">而你……</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">面对现实吧</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">很不聪明:p</span><br/><br/><img border="0" src="https://www.homestuck.com/images/storyfiles/hs2/scraps/jake_bigtext7.gif"/>'
    archive.mspa.story['008520'].title = '[A6A6I2] ====> '
    archive.mspa.story['008520'].content = ''
    archive.mspa.story['008521'].title = '[A6A6I2] ====> '
    archive.mspa.story['008521'].content = ''
    archive.mspa.story['008522'].title = '[A6A6I2] ====> '
    archive.mspa.story['008522'].content = '|DIALOGLOG|<br/><br/><span style="color: #626262">KARKAT: DAVE</span><br/><br/><span style="color: #626262">KARKAT：快点儿DAVE。</span><br/><br/><span style="color: #626262">KARKAT：你他妈看到消息了没。</span><br/><br/><span style="color: #e00707">DAVE：说</span>'
    archive.mspa.story['008523'].title = '[A6A6I2] ====> '
    archive.mspa.story['008523'].content = '|DIALOGLOG|<br/><br/><style>.blur-text { filter: blur(1.2px); }</style><br/><br/><span style="color: #626262" class="blur-text">KARKAT：我们遇到了他妈的大问题</span><br/><br/><span style="color: #e00707">DAVE：啥？</span><br/><br/><span style="color: #626262"  class="blur-text">KARKAT：我说我们他妈的遇到了大问题</span><br/><br/><span style="color: #e00707">DAVE：你说什么</span><br/><br/><span style="color: #626262"  class="blur-text">KARKAT：我说</span><br/><br/><span style="color: #626262" class="blur-text">KARKAT：你他妈的</span><br/><br/><span style="color: #626262"  class="blur-text">KARKAT：是不是又在对着那个小屁股说话</span><br/><br/><span style="color: #e00707">DAVE：老兄你的话全都煳在一起了</span><br/><br/><span style="color: #e00707">DAVE：能不能大点声</span><br/><br/><span style="color: #626262"  class="blur-text">KARKAT：我说我们遇到了</span><br/><br/><span style="color: #e00707">DAVE：再大点</span><br/><br/><span style="color: #626262"  class="blur-text">KARKAT：我说！我们！——</span><br/><br/><span style="color: #e00707">DAVE：大点声好吗哥们</span><br/><br/><span style="color: #e00707">DAVE：泡沫的传声效果真的不怎么样</span></img>'
    archive.mspa.story['008524'].title = '[A6A6I2] ====> '
    archive.mspa.story['008524'].content = '|DIALOGLOG|<br/><br/><span style="color: #626262">KARKAT：我说我们遇到了超他妈巨大的问题就在此时此地！！！！！！</span><br/><br/><span style="color: #e00707">DAVE：我去了</span>'
    archive.mspa.story['008525'].title = '[A6A6I2] ====> '
    archive.mspa.story['008525'].content = ''
    archive.mspa.story['008526'].title = '[A6A6I2] ====> '
    archive.mspa.story['008526'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我的天啊</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">不要再充能了！！！</span><br/><br/><span style="color: #005682">ARANEA：别听她的，Jake！</span><br/><br/><span style="color: #005682">ARANEA：继续提升你的力量，想提多久就提多久！你做得非常棒！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">*咆哮*！！！！！</span>'
    archive.mspa.story['008527'].title = '[A6A6I2] ====> '
    archive.mspa.story['008527'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你以为这就叫提升力量？</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">喂我在问你问题呢爷爷！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你以为这就叫强力？</span><br/><br/><img src="http://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext8.gif" border="0" /><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">让我告诉你什么才叫力量</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">说真的你的“希望力场”简直荒唐透顶而且与绿太阳之怒火相比它什么也不是！！！</span></img>'
    archive.mspa.story['008528'].title = '[A6A6I2] ====> '
    archive.mspa.story['008528'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">呃呃呃呃！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">啊啊啊啊啊啊啊啊！！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">啊啊啊啊啊啊嗷嗷嗷嗷嗷呜！！！</span>'
    archive.mspa.story['008529'].title = '[A6A6I2] ====> '
    archive.mspa.story['008529'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">等等……</span>'
    archive.mspa.story['008530'].title = '[A6A6I2] ====> '
    archive.mspa.story['008530'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我为什么要用我自己的星球替换蛮荒之地？</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我到底在想什么？！</span>'
    archive.mspa.story['008531'].title = '[A6A6I2] ====> '
    archive.mspa.story['008531'].content = '|DIALOGLOG|<br/><br/><img border="0" src="https://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext9.gif"><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">不……</span></img>'
    archive.mspa.story['008532'].title = '[A6A6I2] ====> '
    archive.mspa.story['008532'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">这不可能！</span>'
    archive.mspa.story['008533'].title = '[A6A6I2] ====> '
    archive.mspa.story['008533'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">希望的力量怎么可能……</span>'
    archive.mspa.story['008534'].title = '[A6A6I2] ====> '
    archive.mspa.story['008534'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">这么强？？？？？？？？？？</span>'
    archive.mspa.story['008535'].title = '[A6A6I2] ====> '
    archive.mspa.story['008535'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">呃啊啊啊</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">不</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">不！！</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">这种事情怎么可能发生在我的身上？！</span>'
    archive.mspa.story['008536'].title = '[A6A6I2] ====> '
    archive.mspa.story['008536'].content = '|DIALOGLOG|<br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">你知道你在与谁作对吗？</span><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我就是黑狗化的<span style="font-style: italic">JADE</span>我敲里吗！</span><br/><br/><img border="0" src="https://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext10.gif"><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">我就是最强大的狗女孩！</span><br/><br/><img border="0" src="https://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext11.gif"/><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">纵贯悖论宇宙的历史</span><br/><br/><img border="0" src="https://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext12.gif"/><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000"><span style="font-style: italic">我就是唯一！！！！！！！！！！！！！！！</span></span></img>'
    archive.mspa.story['008537'].title = '[A6A6I2] ====> '
    archive.mspa.story['008537'].content = '|DIALOGLOG|<br/><br/><img border="0" src="https://mspaintadventures.com/storyfiles/hs2/scraps/jake_bigtext13.gif"><br/><br/><span style="color: #4ac925">JADE:</span> <span style="color: #000000">汪呜！</span></img>'
    archive.mspa.story['008538'].title = '[A6A6I2] ====> '
    archive.mspa.story['008538'].content = ''
    archive.mspa.story['008539'].title = '[A6A6I2] ====> '
    archive.mspa.story['008539'].content = ''
    archive.mspa.story['008540'].title = '[A6A6I2] ====> '
    archive.mspa.story['008540'].content = ''
    archive.mspa.story['008541'].title = '[A6A6I2] ====> '
    archive.mspa.story['008541'].content = ''
    archive.mspa.story['008542'].title = '[A6A6I2] ====> '
    archive.mspa.story['008542'].content = '|DIALOGLOG|<br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">JAKE。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你能意识到你对我们的生物学女儿做了什么吗？</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你失控了。立即给我恢复理智。</span><br/><br/><span style="color: #005682">ARANEA：我知道你对你的人类家庭成员有极度的热爱之情，哪怕一台邪恶的电脑腐蚀了你的心智。</span><br/><br/><span style="color: #005682">ARANEA：因此，接下来必须要做的事情让我由衷地心痛。</span><br/><br/><span style="color: #005682">ARANEA：但当她醒来时，她还是会再次被她控制。</span><br/><br/><span style="color: #005682">ARANEA：那时我们该怎么办呢？</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">等等。</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你要干什么？</span>'
    archive.mspa.story['008543'].title = '[A6A6I2] ====> '
    archive.mspa.story['008543'].content = '|DIALOGLOG|<br/><br/><span style="color: #005682">ARANEA：再说一次，我很抱歉。</span><br/><br/><span style="color: #005682">ARANEA：但我必须这样做。</span>'
    archive.mspa.story['008544'].title = '[A6A6I2] ====> '
    archive.mspa.story['008544'].content = ''
    archive.mspa.story['008545'].title = '[A6A6I2] ====> '
    archive.mspa.story['008545'].content = ''
