    archive.mspa.story['008629'].content = ''
    archive.mspa.story['008630'].title = '[A6A6I2] ====> '
    archive.mspa.story['008630'].content = '|DIALOGLOG|<br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">不，给我回来！</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">你们应该先把她放下再去追猫！</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">我的计算表明你们应该先把她放下！</span><br/><br/><span style="color: #e00707">DAVE：喂</span><br/><br/><span style="color: #e00707">DAVE：john的火辣老妈</span><br/><br/><span style="color: #e00707">DAVE：你说你能复活jade是吗</span><br/><br/><span style="color: #00d5f2">JANE:</span> <span style="color: #ff0000">对。</span>'
    archive.mspa.story['008631'].title = '[A6A6I2] ====> '
    archive.mspa.story['008631'].content = '|DIALOGLOG|<br/><br/><span style="color: #e00707">DAVE：对于这事我知道这些就够了</span><br/><br/><span style="color: #e00707">DAVE：在这等我</span><br/><br/><span style="color: #e00707">DAVE：还有，不管你想干什么</span><br/><br/><span style="color: #e00707">DAVE：别把自己弄死好吗</span>'
