    archive.mspa.story['008638'].title = '[A6A6I2] ====> '
    archive.mspa.story['008638'].content = '|DIALOGLOG|<br/><br/><span style="color: #626262">KARKAT：KANAYA等等我！</span><br/><br/><span style="color: #626262">KARKAT：你知道我追不上你的彩虹饮者速度。</span><br/><br/><span style="color: #008141">KANAYA：我的什么</span><br/><br/><span style="color: #626262">KARKAT：他妈的。</span><br/><br/><span style="color: #626262">KARKAT：我们错过了一切！</span><br/><br/><span style="color: #626262">KARKAT：为什么我们是他妈的最后两个不会飞的傻逼？！这事还能再狗屎一点吗？！</span><br/><br/><span style="color: #008141">KANAYA：它就是如此狗屎</span>'
