    archive.mspa.story['008676'].content = '|DIALOGLOG|<br/><br/><span style="color: #2b0057">GAMZEE: TeReZi...</span><br/><br/><span style="color: #2b0057">GAMZEE：呜哇。</span><br/><br/><span style="color: #2b0057">GAMZEE：请停一停。</span><br/><br/><span style="color: #2b0057">GAMZEE：你真的操他妈的……</span><br/><br/><span style="color: #2b0057">GAMZEE：打得我好疼。:o(</span>'
