    archive.mspa.story['008710'].content = '|DIALOGLOG|<br/><br/><span style="color: #b536da">ROSE：不对，等等。</span><br/><br/><span style="color: #b536da">ROSE：这是涉及昏暗位的某种现象吗？</span><br/><br/><span style="color: #b536da">ROSE：我由衷地希望不是。</span>'
    archive.mspa.story['008711'].title = '[A6A6I2] ====> '
    archive.mspa.story['008711'].content = '|DIALOGLOG|<br/><br/><span style="color: #b536da">ROSE：动动脑子，Lalonde，动动脑子。</span><br/><br/><span style="color: #b536da">ROSE：Kanaya教你这部分象限学知识的时候是怎么说的。</span><br/><br/><span style="color: #b536da">ROSE：它应该涉及这么恐怖的互殴吗？</span><br/><br/><span style="color: #b536da">ROSE：我……</span><br/><br/><span style="color: #b536da">ROSE：我不记得了！</span><br/><br/><span style="color: #b536da">ROSE：我在上那堂课的时候可能喝高了！</span><br/><br/><span style="color: #b536da">ROSE：我在说什么鬼话。</span><br/><br/><span style="color: #b536da">ROSE：我在上所有课的时候都喝高了！</span><br/><br/><span style="color: #b536da">ROSE：呃啊，这真的太丢人了。</span><br/><br/><span style="color: #b536da">ROSE：我真的是有史以来最废物的调谐者。</span><br/><br/><span style="color: #b536da">ROSE：最废物的！！！</span>'
