    archive.mspa.story['008878'].title = '[A6A6I4] ====>'
    archive.mspa.story['008878'].content = '|DIALOGLOG|<br/><br/><span style="color: #b536da">ROSE：我……</span><br/><br/><span style="color: #b536da">ROSE：我怎么了？</span><br/><br/><span style="color: #ff6ff2">ROXY：女巫击中了你</span><br/><br/><span style="color: #ff6ff2">ROXY：用她的叉子</span><br/><br/><span style="color: #ff6ff2">ROXY：但你会恢复的</span><br/><br/><span style="color: #b536da">ROSE：噢。</span><br/><br/><span style="color: #b536da">ROSE：那很好。</span><br/><br/><span style="color: #b536da">ROSE：*咳咳咳*。</span><br/><br/><span style="color: #ff6ff2">ROXY：也许你现在，呃</span><br/><br/><span style="color: #ff6ff2">ROXY：不该着急说话</span><br/><br/><span style="color: #b536da">ROSE：你救了我，是吗？</span><br/><br/><span style="color: #ff6ff2">ROXY: ...</span><br/><br/><span style="color: #b536da">ROSE：谢谢。</span><br/><br/><span style="color: #b536da">ROSE：可是，</span><br/><br/><span style="color: #b536da">ROSE：她不会回来了，是不是。</span><br/><br/><span style="color: #b536da">ROSE：我是说。再也不会。</span><br/><br/><span style="color: #ff6ff2">ROXY: ？</span><br/><br/><span style="color: #b536da">ROSE：我看到她死去。</span><br/><br/><span style="color: #b536da">ROSE：而且</span><br/><br/><span style="color: #b536da">ROSE：太可悲了……</span><br/><br/><span style="color: #b536da">ROSE：*咳咳*。</span><br/><br/><span style="color: #b536da">ROSE：太可悲了我甚至还从来没有……</span><br/><br/><span style="color: #b536da">ROSE：找机会告诉她……</span><br/><br/><span style="color: #b536da">ROSE：我爱她。</span><br/><br/><span style="color: #ff6ff2">ROXY：谁？</span>'
