    archive.mspa.story['009028'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：嗨呀！</span>'
    archive.mspa.story['009029'].title = '[A6A6I4] ====>'
    archive.mspa.story['009029'].content = ''
