    archive.mspa.story['009141'].content = ''
    archive.mspa.story['009142'].title = '[A6A6I4] ====>'
    archive.mspa.story['009142'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：所以……</span><br/><br/><span style="color: #0715cd">JOHN：你就只是想让我去你家里，偷走一只玩偶龙？</span><br/><br/><span style="color: #0715cd">JOHN：这种事是要怎么在时间线里占据一星半点的重要性？</span>'
    archive.mspa.story['009143'].title = '[A6A6I4] ====>'
    archive.mspa.story['009143'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：算了。</span><br/><br/><span style="color: #0715cd">JOHN：万一偷走这条龙就是愚蠢的跨时间胡搞史上最重要的事件呢？</span><br/><br/><span style="color: #0715cd">JOHN：我是谁啊，哪里轮得到我来做判断。</span><br/><br/><span style="color: #0715cd">JOHN：走吧，下一站是……</span>'
    archive.mspa.story['009144'].title = '[A6A6I4] ====>'
    archive.mspa.story['009144'].content = ''
    archive.mspa.story['009145'].title = '[A6A6I4] ====>'
