    archive.mspa.story['009147'].content = ''
    archive.mspa.story['009148'].title = '[A6A6I4] ====>'
    archive.mspa.story['009148'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：“4刻（MOM3NT）”？</span><br/><br/><span style="color: #0715cd">JOHN：哇，这个听起来好宽泛。</span><br/><br/><span style="color: #0715cd">JOHN：你指的是什么时刻，terezi？</span><br/><br/><span style="color: #0715cd">JOHN：总得缩小一下范围吧。</span>'
    archive.mspa.story['009149'].title = '[A6A6I4] ====>'
    archive.mspa.story['009149'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：也许我很快就会知道了。最好是个好时刻！</span>'
