    archive.mspa.story['009185'].content = '|DIALOGLOG|<br/><br/><span style="color: #008282">DRAGONSPRITE：*嗅嗅*</span><br/><br/><span style="color: #008282">DRAGONSPRITE：*嗅嗅嗅嗅*</span><br/><br/><span style="color: #0715cd">JOHN：（嘿，可以别这样吗！）</span><br/><br/><span style="color: #0715cd">JOHN：（我正在拼命降低我的存在感呢。）</span>'
