    archive.mspa.story['009266'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：TEREZI，不要！</span><br/><br/><span style="color: #0715cd">JOHN：别这样！！！</span>'
    archive.mspa.story['009267'].title = '[A6A6I4] ====>'
    archive.mspa.story['009267'].content = '|DIALOGLOG|<br/><br/><span style="color: #005682">VRISKA: John？？？？？？？？</span>'
    archive.mspa.story['009268'].title = '[A6A6I4] ====>'
    archive.mspa.story['009268'].content = '|DIALOGLOG|<br/><br/><span style="color: #005682">VRISKA：你怎么在这呃呜！！！！！！！！</span><br/><br/><span style="color: #0715cd">JOHN：咚！</span><br/><br/><span style="color: #008282">TEREZI：JOHN站住！&gt;:O</span>'
    archive.mspa.story['009269'].title = '[A6A6I4] ====>'
