    archive.mspa.story['009365'].title = '[A6A6I5] ====>'
    archive.mspa.story['009365'].content = '|DIALOGLOG|<br/><br/><span style="color: #005682">VRISKA：嗨，John！！！！！！！！</span>'
    archive.mspa.story['009366'].title = '[A6A6I5] ====>'
    archive.mspa.story['009366'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：哇……</span>'
    archive.mspa.story['009367'].title = '[A6A6I5] ====>'
    archive.mspa.story['009367'].content = '|DIALOGLOG|<br/><br/><span style="color: #0715cd">JOHN：嗨，大家好！</span><br/><br/><span style="color: #e00707">DAVE：（哇哦）</span><br/><br/><span style="color: #e00707">DAVE：（哇哦）</span><br/><br/><span style="color: #e00707">DAVE：（他真的出现了是不是）</span><br/><br/><span style="color: #626262">KARKAT：嗨JOHN</span><br/><br/><span style="color: #e00707">DAVE：（哇哦）</span><br/><br/><span style="color: #626262">KARKAT：（不要再哇哦个没完了你这没礼貌的笨逼，快点问好）</span><br/><br/><span style="color: #e00707">DAVE：哦对，嗨john</span><br/><br/><span style="color: #e00707">DAVE：最近如何</span><br/><br/><span style="color: #0715cd">JOHN：嗨dave，还行吧！</span><br/><br/><span style="color: #0715cd">JOHN：又见面了，嗨karkat！</span><br/><br/><span style="color: #0715cd">JOHN：哈哈，其实我刚在大概五分钟前和你见过面，不过我想从你的角度来看可能已经过了好几年了，我去。</span><br/><br/><span style="color: #0715cd">JOHN：你们大概经历了一大堆有的没的蠢事，是不是？</span><br/><br/><span style="color: #0715cd">JOHN：噢算了当我没说，你不需要回答这个问题。我们还有很多交流情报的时间！</span><br/><br/><span style="color: #0715cd">JOHN：嗨，所有的其他人！</span><br/><br/><span style="color: #0715cd">JOHN：噢我的天哪，我想死你们了！包括我不太认识或者还没认识的几位。</span><br/><br/><span style="color: #0715cd">JOHN：哦！！！</span><br/><br/><span style="color: #0715cd">JOHN：对了，这是roxy。</span><br/><br/><span style="color: #0715cd">JOHN：她是我新认识的朋友，我们刚刚经历了一段疯狂的冒险，就是修正时间线然后再找到你们之类的。</span><br/><br/><span style="color: #0715cd">JOHN：总之我们回来了！</span><br/><br/><span style="color: #ff6ff2">ROXY：嗯哼</span>'
    archive.mspa.story['009368'].title = '[A6A6I5] ====>'
    archive.mspa.story['009368'].content = '|DIALOGLOG|<br/><br/><span style="color: #ff6ff2">ROXY：哈哈</span><br/><br/><span style="color: #ff6ff2">ROXY：嗨</span>'
