    archive.mspa.story['009662'].title = '[A6A6I5] ====>'
    archive.mspa.story['009662'].content = '|DIALOGLOG|<br/><br/><span style="color: #e00707">DAVE：为我现在的行为</span><br/><br/><span style="color: #e00707">DAVE：这场正在发生的狗屎烂蛋</span><br/><br/><span style="color: #f2a400">DIRK：哦<br/><br/>DIRK：这……</span><br/><br/><span style="color: #e00707">DAVE：我</span>'
    archive.mspa.story['009663'].title = '[A6A6I5] ====>'
    archive.mspa.story['009663'].content = '|DIALOGLOG|<br/><br/><span style="color: #e00707">DAVE：我这个人真的很糟糕<br/><br/>DAVE：所以才会像现在这样<br/><br/>DAVE：所以<br/><br/>DAVE：对不起</span><br/><br/><span style="color: #f2a400">DIRK：哦，呃，<br/><br/>DIRK：嗯。<br/><br/>DIRK：老兄。<br/><br/>DIRK：这就是狗屎烂蛋好吧。</span><br/><br/><span style="color: #e00707">DAVE：我知道</span>'
